def getNetworks(status=None, page=None, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getNetworks"

    # ---- rate limiting / usage logging (best-effort; no schema given) ----
    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    # Simple global rate limit: 120 req/min across datastore
    window_s = 60
    limit_per_window = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
    if recent >= limit_per_window:
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "RATE_LIMIT",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save(logs_file, logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- validation ----
    if page is None:
        page = 0
    if limit is None:
        limit = 10

    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or int(page) < 0:
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "page must be an integer >= 0")
    if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit or not (1 <= int(limit) <= 100):
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    page = int(page)
    limit = int(limit)

    if status is not None:
        if not isinstance(status, str):
            row = {
                "id": f"req_{int(time.time()*1000)}",
                "timestamp": now_iso,
                "endpoint": endpoint,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(row)
            _save(logs_file, logs)
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "maintenance", "deprecated"):
            row = {
                "id": f"req_{int(time.time()*1000)}",
                "timestamp": now_iso,
                "endpoint": endpoint,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(row)
            _save(logs_file, logs)
            return _err("VALIDATION_ERROR", "status must be one of active|maintenance|deprecated")

    # ---- read + business rules ----
    networks = _load("networks.json")
    if not isinstance(networks, list):
        networks = []

    # Default: hide deprecated unless explicitly requested
    if status is None:
        rows = [n for n in networks if isinstance(n, dict) and n.get("status") != "deprecated"]
    else:
        rows = [n for n in networks if isinstance(n, dict) and n.get("status") == status]

    # Stable ordering: by name then id
    def _k(n):
        name = n.get("name")
        nid = n.get("id")
        return ((name or "").lower(), (nid or "").lower())
    rows.sort(key=_k)

    total = len(rows)
    start = page * limit
    end = start + limit
    page_rows = rows[start:end]
    has_more = end < total
    next_cursor = str(page + 1) if has_more else None

    out = {
        "data": page_rows,
        "meta": {
            "page": page,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

    row = {
        "id": f"req_{int(time.time()*1000)}",
        "timestamp": now_iso,
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(row)
    _save(logs_file, logs)
    return out

def getNetworkDexes(network, page=None, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getNetworkDexes"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    # ---- request logs + rate limit (global, using request_logs.json if present) ----
    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    # 120 req / minute global (as used elsewhere in this codebase)
    window_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs[-5000:]:
        if not isinstance(r, dict):
            continue
        dt = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if dt and dt >= window_start:
            cnt += 1
    if cnt >= 120:
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "page": page, "limit": limit},
            "status": "RATE_LIMIT",
            "message": "Too many requests",
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save(logs_file, logs)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=120, observed=cnt)

    def _finish(status_code, payload=None, message=None, **extra):
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "page": page, "limit": limit},
            "status": status_code,
            "message": message,
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save(logs_file, logs)
        if payload is not None:
            return payload
        return _err(status_code, message or "Request failed", **extra)

    # ---- validation ----
    if not isinstance(network, str) or not network.strip():
        return _finish("VALIDATION_ERROR", None, "network must be a non-empty string")

    if page is None:
        page = 0
    if limit is None:
        limit = 10

    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or int(page) < 0:
        return _finish("VALIDATION_ERROR", None, "page must be an integer >= 0", page=page)
    page = int(page)

    if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit:
        return _finish("VALIDATION_ERROR", None, "limit must be an integer between 1 and 100", limit=limit)
    limit = int(limit)
    if limit < 1 or limit > 100:
        return _finish("VALIDATION_ERROR", None, "limit must be an integer between 1 and 100", limit=limit)

    # ---- resolve network: accept both canonical ids and common slugs (e.g., 'base') ----
    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("data") or networks.get("items") or networks.get("networks") or []
    if not isinstance(networks, list):
        networks = []
    needle = network.strip().lower()

    net_row = None
    for n in networks:
        if not isinstance(n, dict):
            continue
        nid = (n.get("id") or "").strip()
        nm = (n.get("name") or "").strip()
        if nid.lower() == needle:
            net_row = n
            break
        # allow "dxn_xxx" ids to be matched by suffix "xxx"
        if nid.lower().startswith("dxn_") and nid.lower()[4:] == needle:
            net_row = n
            break
        if nm and nm.lower() == needle:
            net_row = n
            break
    if net_row is None:
        return _finish("NOT_FOUND", None, "Network not found", network=network)

    dexes = _load("dexes.json")
    if isinstance(dexes, dict) and "rows" in dexes:
        dexes = dexes.get("data") or dexes.get("items") or []
    if not isinstance(dexes, list):
        dexes = []

    net_id = net_row.get("id")
    rows = [d for d in dexes if isinstance(d, dict) and d.get("network_id") == net_id and d.get("status") == "active"]

    total = len(rows)
    start = page * limit
    end = start + limit
    items = rows[start:end] if start < total else []

    payload = {
        "network": {"id": net_row.get("id"), "name": net_row.get("name")},
        "page": page,
        "limit": limit,
        "total": total,
        "has_more": end < total,
        "dexes": items,
    }
    return _finish("OK", payload)

def getTopPools(page=None, limit=None, sort=None, orderBy=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getTopPools"

    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    # global rate limit: 120 req/min
    window_s = 60
    limit_per_window = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
    if recent >= limit_per_window:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "RATE_LIMIT",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_file, logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    if page is None:
        page = 0
    if limit is None:
        limit = 10
    if sort is None:
        sort = "desc"
    if orderBy is None:
        orderBy = "volume_usd"

    # validation
    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or int(page) < 0:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "page must be an integer >= 0")
    if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit or not (1 <= int(limit) <= 100):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if not isinstance(sort, str) or sort not in ("asc", "desc"):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "sort must be one of asc|desc")
    if not isinstance(orderBy, str) or orderBy not in ("volume_usd", "price_usd", "transactions", "last_price_change_usd_24h", "created_at"):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": now_iso,
            "endpoint": endpoint,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "orderBy is not supported")

    page = int(page)
    limit = int(limit)

    pools = _load("pools.json")
    if not isinstance(pools, list):
        pools = []

    # Only active pools
    rows = [p for p in pools if isinstance(p, dict) and p.get("status") == "active"]

    order_map = {
        "volume_usd": "volume_usd_24h",
        "price_usd": "price_usd",
        "transactions": "transactions_24h",
        "last_price_change_usd_24h": "last_price_change_usd_24h",
        "created_at": "__created_at_special__",
    }

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _key(p):
        if order_map[orderBy] == "__created_at_special__":
            v = _dt(p.get("created_on_chain_at")) or _dt(p.get("created_at"))
            # None sorts last
            return (v is None, v or datetime.datetime.min, (p.get("id") or ""))
        field = order_map[orderBy]
        v = p.get(field)
        if v is None:
            # None sorts last for both directions by using tuple prefix
            return (1, 0, (p.get("id") or ""))
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return (0, float(v), (p.get("id") or ""))
        # non-numeric fallback
        return (0, 0, (p.get("id") or ""))

    reverse = (sort == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    start = page * limit
    end = start + limit
    page_rows = rows[start:end]
    has_more = end < total
    next_cursor = str(page + 1) if has_more else None

    out = {
        "data": page_rows,
        "meta": {
            "page": page,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "orderBy": orderBy,
            "sort": sort,
        },
    }

    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "timestamp": now_iso,
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save(logs_file, logs)
    return out

def getNetworkPools(network, page=None, limit=None, sort=None, orderBy=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getNetworkPools"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _norm_addr(a):
        if not isinstance(a, str):
            return None
        s = a.strip()
        if not s:
            return None
        if s.lower().startswith("0x"):
            return "0x" + s[2:].lower()
        return s.lower()

    # ---- logs + RL ----
    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs[-5000:]:
        if not isinstance(r, dict):
            continue
        dt = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if dt and dt >= window_start:
            cnt += 1
    if cnt >= 120:
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "page": page, "limit": limit, "sort": sort, "orderBy": orderBy},
            "status": "RATE_LIMIT",
            "message": "Too many requests",
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save(logs_file, logs)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=120, observed=cnt)

    def _finish(status_code, payload=None, message=None, **extra):
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "page": page, "limit": limit, "sort": sort, "orderBy": orderBy},
            "status": status_code,
            "message": message,
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save(logs_file, logs)
        if payload is not None:
            return payload
        return _err(status_code, message or "Request failed", **extra)

    # ---- validation ----
    if not isinstance(network, str) or not network.strip():
        return _finish("VALIDATION_ERROR", None, "network must be a non-empty string")
    if page is None:
        page = 0
    if limit is None:
        limit = 10
    if sort is None:
        sort = "desc"
    if orderBy is None:
        orderBy = "volume_usd"

    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or int(page) < 0:
        return _finish("VALIDATION_ERROR", None, "page must be an integer >= 0", page=page)
    page = int(page)

    if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit:
        return _finish("VALIDATION_ERROR", None, "limit must be an integer between 1 and 100", limit=limit)
    limit = int(limit)
    if limit < 1 or limit > 100:
        return _finish("VALIDATION_ERROR", None, "limit must be an integer between 1 and 100", limit=limit)

    if sort not in ("asc", "desc"):
        return _finish("VALIDATION_ERROR", None, "sort must be 'asc' or 'desc'", sort=sort)

    order_map = {
        "volume_usd": "volume_usd_24h",
        "price_usd": "price_usd",
        "transactions": "transactions_24h",
        "last_price_change_usd_24h": "last_price_change_usd_24h",
        "created_at": "created_on_chain_at",
    }
    if orderBy not in order_map:
        return _finish("VALIDATION_ERROR", None, "Unsupported orderBy", orderBy=orderBy)

    # ---- resolve network (accept suffix/slugs) ----
    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("data") or networks.get("items") or []
    if not isinstance(networks, list):
        networks = []
    needle = network.strip().lower()

    net_row = None
    for n in networks:
        if not isinstance(n, dict):
            continue
        nid = (n.get("id") or "").strip()
        nm = (n.get("name") or "").strip()
        if nid.lower() == needle or (nid.lower().startswith("dxn_") and nid.lower()[4:] == needle) or (nm and nm.lower() == needle):
            net_row = n
            break
    if net_row is None:
        return _finish("NOT_FOUND", None, "Network not found", network=network)

    pools = _load("pools.json")
    if isinstance(pools, dict) and "rows" in pools:
        pools = pools.get("data") or pools.get("items") or []
    if not isinstance(pools, list):
        pools = []

    net_id = net_row.get("id")
    rows = [p for p in pools if isinstance(p, dict) and p.get("network_id") == net_id and p.get("status") == "active"]

    sort_field = order_map[orderBy]
    reverse = (sort == "desc")

    def _key(p):
        v = p.get(sort_field)
        if orderBy == "created_at":
            v = p.get("created_on_chain_at") or p.get("created_at")
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1)
        if v is None:
            return float("-inf") if reverse else float("inf")
        try:
            return float(v)
        except Exception:
            return float("-inf") if reverse else float("inf")

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    start_i = page * limit
    end_i = start_i + limit
    items = rows[start_i:end_i] if start_i < total else []

    payload = {
        "network": {"id": net_row.get("id"), "name": net_row.get("name")},
        "page": page,
        "limit": limit,
        "orderBy": orderBy,
        "sort": sort,
        "total": total,
        "has_more": end_i < total,
        "pools": items,
    }
    return _finish("OK", payload)

