            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    # ---- logs + RL ----
    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs[-5000:]:
        if not isinstance(r, dict):
            continue
        dt = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if dt and dt >= window_start:
            cnt += 1
    if cnt >= 120:
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "dex": dex, "page": page, "limit": limit, "sort": sort, "orderBy": orderBy},
            "status": "RATE_LIMIT",
            "message": "Too many requests",
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save(logs_file, logs)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=120, observed=cnt)

    def _finish(status_code, payload=None, message=None, **extra):
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "dex": dex, "page": page, "limit": limit, "sort": sort, "orderBy": orderBy},
            "status": status_code,
            "message": message,
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save(logs_file, logs)
        if payload is not None:
            return payload
        return _err(status_code, message or "Request failed", **extra)

    # ---- validation ----
    if not isinstance(network, str) or not network.strip():
        return _finish("VALIDATION_ERROR", None, "network must be a non-empty string")
    if not isinstance(dex, str) or not dex.strip():
        return _finish("VALIDATION_ERROR", None, "dex must be a non-empty string")

    if page is None:
        page = 0
    if limit is None:
        limit = 10
    if sort is None:
        sort = "desc"
    if orderBy is None:
        orderBy = "volume_usd"

    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or int(page) < 0:
        return _finish("VALIDATION_ERROR", None, "page must be an integer >= 0", page=page)
    page = int(page)

    if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit:
        return _finish("VALIDATION_ERROR", None, "limit must be an integer between 1 and 100", limit=limit)
    limit = int(limit)
    if limit < 1 or limit > 100:
        return _finish("VALIDATION_ERROR", None, "limit must be an integer between 1 and 100", limit=limit)

    if sort not in ("asc", "desc"):
        return _finish("VALIDATION_ERROR", None, "sort must be 'asc' or 'desc'", sort=sort)

    order_map = {
        "volume_usd": "volume_usd_24h",
        "price_usd": "price_usd",
        "transactions": "transactions_24h",
        "last_price_change_usd_24h": "last_price_change_usd_24h",
        "created_at": "created_on_chain_at",
    }
    if orderBy not in order_map:
        return _finish("VALIDATION_ERROR", None, "Unsupported orderBy", orderBy=orderBy)

    # ---- resolve network, then dex by id OR slug within network ----
    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("data") or networks.get("items") or []
    if not isinstance(networks, list):
        networks = []
    needle = network.strip().lower()

    net_row = None
    for n in networks:
        if not isinstance(n, dict):
            continue
        nid = (n.get("id") or "").strip()
        nm = (n.get("name") or "").strip()
        if nid.lower() == needle or (nid.lower().startswith("dxn_") and nid.lower()[4:] == needle) or (nm and nm.lower() == needle):
            net_row = n
            break
    if net_row is None:
        return _finish("NOT_FOUND", None, "Network not found", network=network)

    dexes = _load("dexes.json")
    if isinstance(dexes, dict) and "rows" in dexes:
        dexes = dexes.get("data") or dexes.get("items") or []
    if not isinstance(dexes, list):
        dexes = []

    net_id = net_row.get("id")
    dex_needle = dex.strip().lower()
    dex_row = None
    for d in dexes:
        if not isinstance(d, dict) or d.get("network_id") != net_id:
            continue
        if (d.get("id") or "").strip().lower() == dex_needle or (d.get("slug") or "").strip().lower() == dex_needle:
            dex_row = d
            break
    if dex_row is None:
        return _finish("NOT_FOUND", None, "DEX not found on this network", network=network, dex=dex)

    pools = _load("pools.json")
    if isinstance(pools, dict) and "rows" in pools:
        pools = pools.get("data") or pools.get("items") or []
    if not isinstance(pools, list):
        pools = []

    rows = [p for p in pools if isinstance(p, dict) and p.get("network_id") == net_id and p.get("dex_id") == dex_row.get("id") and p.get("status") == "active"]

    sort_field = order_map[orderBy]
    reverse = (sort == "desc")

    def _key(p):
        if orderBy == "created_at":
            v = p.get("created_on_chain_at") or p.get("created_at")
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1)
        v = p.get(sort_field)
        if v is None:
            return float("-inf") if reverse else float("inf")
        try:
            return float(v)
        except Exception:
            return float("-inf") if reverse else float("inf")

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    start_i = page * limit
    end_i = start_i + limit
    items = rows[start_i:end_i] if start_i < total else []

    payload = {
        "network": {"id": net_row.get("id"), "name": net_row.get("name")},
        "dex": {"id": dex_row.get("id"), "slug": dex_row.get("slug"), "name": dex_row.get("name")},
        "page": page,
        "limit": limit,
        "orderBy": orderBy,
        "sort": sort,
        "total": total,
        "has_more": end_i < total,
        "pools": items,
    }
    return _finish("OK", payload)

def getPoolDetails(network, poolAddress, inversed=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getPoolDetails"
    logs_file = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.isoformat() + "Z"

    def _parse_dt_log(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _norm(s):
        if not isinstance(s, str):
            return None
        v = s.strip()
        if not v:
            return None
        if v.lower().startswith("0x"):
            return "0x" + v[2:].lower()
        return v.lower()

    def _append_log(status, message=None, **extra):
        logs = _load(logs_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "request": {"network": network, "poolAddress": poolAddress, "inversed": inversed},
                "status": status,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(_now()),
                **extra,
            }
        )
        _save(logs_file, logs)

    # Rate limit: global 60s window
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    observed = 0
    for r in logs[-5000:]:
        if isinstance(r, dict):
            dt = _parse_dt_log(r.get("created_at") or r.get("timestamp"))
            if dt and dt >= window_start:
                observed += 1
    limit_rl = 240
    if observed >= limit_rl:
        _append_log("RATE_LIMIT", "Too many requests", window_seconds=60, limit=limit_rl, observed=observed)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=limit_rl, observed=observed)

    # Validation (relaxed: accept any non-empty string; normalize for lookup)
    if not isinstance(network, str) or not network.strip():
        _append_log("VALIDATION_ERROR", "network must be a non-empty string", network=network)
        return _err("VALIDATION_ERROR", "network must be a non-empty string", network=network)
    if not isinstance(poolAddress, str) or not poolAddress.strip():
        _append_log("VALIDATION_ERROR", "poolAddress must be a non-empty string", poolAddress=poolAddress)
        return _err("VALIDATION_ERROR", "poolAddress must be a non-empty string", poolAddress=poolAddress)
    if inversed is None:
        inversed = False
    if not isinstance(inversed, bool):
        _append_log("VALIDATION_ERROR", "inversed must be a boolean", inversed=inversed)
        return _err("VALIDATION_ERROR", "inversed must be a boolean", inversed=inversed)

    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("rows")
    if not isinstance(networks, list):
        networks = []
    dexes = _load("dexes.json")
    if isinstance(dexes, dict) and "rows" in dexes:
        dexes = dexes.get("rows")
    if not isinstance(dexes, list):
        dexes = []
    tokens = _load("tokens.json")
    if isinstance(tokens, dict) and "rows" in tokens:
        tokens = tokens.get("rows")
    if not isinstance(tokens, list):
        tokens = []
    pools = _load("pools.json")
    if isinstance(pools, dict) and "rows" in pools:
        pools = pools.get("rows")
    if not isinstance(pools, list):
        pools = []

    net_key = network.strip().lower()

    def _net_match(nr):
        if not isinstance(nr, dict):
            return False
        nid = (nr.get("id") or "").strip().lower()
        name = (nr.get("name") or "").strip().lower()
        # Accept both id and name as "network" to be resilient to caller inputs.
        return nid == net_key or (name and name == net_key)

    net = next((n for n in networks if _net_match(n)), None)
    if not net:
        _append_log("NOT_FOUND", "Network not found", network=network)
        return _err("NOT_FOUND", "Network not found", network=network)

    addr_norm = _norm(poolAddress)
    if not addr_norm:
        _append_log("VALIDATION_ERROR", "poolAddress is malformed", poolAddress=poolAddress)
        return _err("VALIDATION_ERROR", "poolAddress is malformed", poolAddress=poolAddress)

    pool = None
    for p in pools:
        if not isinstance(p, dict):
            continue
        if (p.get("network_id") or "").strip().lower() != (net.get("id") or "").strip().lower():
            continue
        if _norm(p.get("address_normalized") or p.get("address_raw") or "") == addr_norm:
            pool = p
            break
    if not pool:
        _append_log("NOT_FOUND", "Pool not found", network=network, poolAddress=poolAddress)
        return _err("NOT_FOUND", "Pool not found", network=network, poolAddress=poolAddress)

    dex = None
    if pool.get("dex_id"):
        did = (pool.get("dex_id") or "").strip()
        dex = next((d for d in dexes if isinstance(d, dict) and d.get("id") == did), None)

    def _token_by_id(tid):
        return next((t for t in tokens if isinstance(t, dict) and t.get("id") == tid), None)

    token0 = _token_by_id(pool.get("token0_id"))
    token1 = _token_by_id(pool.get("token1_id"))

    # Build response, applying inverse presentation without mutating stored rows
    out_pool = dict(pool)

    def _inv_num(x):
        try:
            xv = float(x)
        except Exception:
            return x
        if xv == 0:
            return None
        return 1.0 / xv

    if inversed:
        # swap tokens for presentation
        out_pool["token0_id"], out_pool["token1_id"] = out_pool.get("token1_id"), out_pool.get("token0_id")
        token0, token1 = token1, token0
        # invert price_usd if present (best-effort)
        if out_pool.get("price_usd") is not None:
            out_pool["price_usd"] = _inv_num(out_pool.get("price_usd"))

    resp = {
        "network": {"id": net.get("id"), "name": net.get("name"), "chain_id": net.get("chain_id"), "native_symbol": net.get("native_symbol")},
        "dex": None if not dex else {"id": dex.get("id"), "slug": dex.get("slug"), "name": dex.get("name"), "status": dex.get("status"), "website_url": dex.get("website_url")},
        "pool": out_pool,
        "token0": token0,
        "token1": token1,
        "inversed": inversed,
    }

    _append_log("OK", None, network_id=net.get("id"), pool_id=pool.get("id"))
    return resp

