        "created_at": ("created_on_chain_at", "created_at"),
    }
    if orderBy not in order_map:
        _append_log("VALIDATION_ERROR", "Unsupported orderBy", orderBy=orderBy)
        return _err("VALIDATION_ERROR", "Unsupported orderBy", orderBy=orderBy)

    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("rows")
    if not isinstance(networks, list):
        networks = []

    tokens = _load("tokens.json")
    if isinstance(tokens, dict) and "rows" in tokens:
        tokens = tokens.get("rows")
    if not isinstance(tokens, list):
        tokens = []

    pools = _load("pools.json")
    if isinstance(pools, dict) and "rows" in pools:
        pools = pools.get("rows")
    if not isinstance(pools, list):
        pools = []

    net_key = network.strip().lower()

    def _net_match(nr):
        if not isinstance(nr, dict):
            return False
        nid = (nr.get("id") or "").strip().lower()
        name = (nr.get("name") or "").strip().lower()
        return nid == net_key or (name and name == net_key)

    net = next((n for n in networks if _net_match(n)), None)
    if not net:
        _append_log("NOT_FOUND", "Network not found", network=network)
        return _err("NOT_FOUND", "Network not found", network=network)

    primary_norm = _norm(tokenAddress)
    if not primary_norm:
        _append_log("VALIDATION_ERROR", "tokenAddress is malformed", tokenAddress=tokenAddress)
        return _err("VALIDATION_ERROR", "tokenAddress is malformed", tokenAddress=tokenAddress)

    token = None
    for t in tokens:
        if not isinstance(t, dict):
            continue
        if (t.get("network_id") or "").strip().lower() != (net.get("id") or "").strip().lower():
            continue
        if _norm(t.get("address_normalized") or t.get("address_raw") or "") == primary_norm:
            token = t
            break
    if not token:
        _append_log("NOT_FOUND", "Token not found", network=network, tokenAddress=tokenAddress)
        return _err("NOT_FOUND", "Token not found", network=network, tokenAddress=tokenAddress)

    other_token = None
    other_norm = None
    if address is not None:
        if not isinstance(address, str) or not address.strip():
            _append_log("VALIDATION_ERROR", "address must be a non-empty string when provided", address=address)
            return _err("VALIDATION_ERROR", "address must be a non-empty string when provided", address=address)
        other_norm = _norm(address)
        if not other_norm:
            _append_log("VALIDATION_ERROR", "address is malformed", address=address)
            return _err("VALIDATION_ERROR", "address is malformed", address=address)
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if (t.get("network_id") or "").strip().lower() != (net.get("id") or "").strip().lower():
                continue
            if _norm(t.get("address_normalized") or t.get("address_raw") or "") == other_norm:
                other_token = t
                break
        if not other_token:
            _append_log("NOT_FOUND", "Additional token not found", network=network, address=address)
            return _err("NOT_FOUND", "Additional token not found", network=network, address=address)

    # Filter pools that include primary token; optionally also include the other token
    token_id = token.get("id")
    other_id = other_token.get("id") if other_token else None

    filtered = []
    for p in pools:
        if not isinstance(p, dict):
            continue
        if (p.get("network_id") or "").strip().lower() != (net.get("id") or "").strip().lower():
            continue
        t0 = p.get("token0_id")
        t1 = p.get("token1_id")
        if t0 != token_id and t1 != token_id:
            continue
        if other_id is not None and not ((t0 == token_id and t1 == other_id) or (t0 == other_id and t1 == token_id)):
            continue
        filtered.append(p)

    def _parse_dt_any(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _order_key(p):
        fields = order_map[orderBy]
        val = None
        for f in fields:
            if p.get(f) is not None:
                val = p.get(f)
                break
        if orderBy == "created_at":
            dt = _parse_dt_any(val) if isinstance(val, str) else None
            if dt is None:
                dt = _parse_dt_any(p.get("created_at")) if isinstance(p.get("created_at"), str) else None
            return dt or datetime.datetime(1970, 1, 1)
        try:
            return float(val) if val is not None else float("-inf")
        except Exception:
            return float("-inf")

    reverse = sort == "desc"
    filtered.sort(key=_order_key, reverse=reverse)

    total = len(filtered)
    start_i = page * limit
    end_i = start_i + limit
    items = filtered[start_i:end_i] if start_i < total else []
    has_more = end_i < total

    _append_log("OK", None, network_id=net.get("id"), token_id=token_id, total=total, returned=len(items))
    return {
        "network": {"id": net.get("id"), "name": net.get("name")},
        "token": {"id": token.get("id"), "address_normalized": token.get("address_normalized"), "symbol": token.get("symbol"), "name": token.get("name")},
        "other_token": None if not other_token else {"id": other_token.get("id"), "address_normalized": other_token.get("address_normalized"), "symbol": other_token.get("symbol"), "name": other_token.get("name")},
        "items": items,
        "page": page,
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": None,
    }

def getPoolOHLCV(network, poolAddress, start, end=None, limit=None, interval=None, inversed=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getPoolOHLCV"
    logs_file = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.isoformat() + "Z"

    def _parse_dt_log(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _parse_any_dt(v):
        if v is None or isinstance(v, bool):
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(int(v))
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.isdigit():
            try:
                return datetime.datetime.utcfromtimestamp(int(s))
            except Exception:
                return None
        if len(s) == 10 and s[4] == "-" and s[7] == "-":
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _norm(s):
        if not isinstance(s, str):
            return None
        v = s.strip()
        if not v:
            return None
        if v.lower().startswith("0x"):
            return "0x" + v[2:].lower()
        return v.lower()

    def _append_log(status, message=None, **extra):
        logs = _load(logs_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "request": {"network": network, "poolAddress": poolAddress, "start": start, "end": end, "limit": limit, "interval": interval, "inversed": inversed},
                "status": status,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(_now()),
                **extra,
            }
        )
        _save(logs_file, logs)

    # rate limit
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    observed = 0
    for r in logs[-5000:]:
        if isinstance(r, dict):
            dt = _parse_dt_log(r.get("created_at") or r.get("timestamp"))
            if dt and dt >= window_start:
                observed += 1
    limit_rl = 240
    if observed >= limit_rl:
        _append_log("RATE_LIMIT", "Too many requests", window_seconds=60, limit=limit_rl, observed=observed)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=limit_rl, observed=observed)

    if inversed is None:
        inversed = False
    if interval is None:
        interval = "24h"
    if limit is None:
        limit = 1

    if not isinstance(network, str) or not network.strip():
        _append_log("VALIDATION_ERROR", "network must be a non-empty string", network=network)
        return _err("VALIDATION_ERROR", "network must be a non-empty string", network=network)
    if not isinstance(poolAddress, str) or not poolAddress.strip():
        _append_log("VALIDATION_ERROR", "poolAddress must be a non-empty string", poolAddress=poolAddress)
        return _err("VALIDATION_ERROR", "poolAddress must be a non-empty string", poolAddress=poolAddress)
    if not isinstance(inversed, bool):
        _append_log("VALIDATION_ERROR", "inversed must be a boolean", inversed=inversed)
        return _err("VALIDATION_ERROR", "inversed must be a boolean", inversed=inversed)

    if isinstance(limit, bool) or (not isinstance(limit, (int, float))) or (isinstance(limit, float) and not limit.is_integer()):
        _append_log("VALIDATION_ERROR", "limit must be an integer between 1 and 366", limit=limit)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 366", limit=limit)
    limit = int(limit)
    if limit < 1 or limit > 366:
        _append_log("VALIDATION_ERROR", "limit must be an integer between 1 and 366", limit=limit)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 366", limit=limit)

    if not isinstance(interval, str) or not interval.strip():
        _append_log("VALIDATION_ERROR", "interval must be a non-empty string", interval=interval)
        return _err("VALIDATION_ERROR", "interval must be a non-empty string", interval=interval)
    interval = interval.strip()

    start_dt = _parse_any_dt(start)
    if not start_dt:
        _append_log("VALIDATION_ERROR", "start cannot be parsed", start=start)
        return _err("VALIDATION_ERROR", "start cannot be parsed", start=start)

    end_dt = _parse_any_dt(end) if end is not None else None
    if end is not None and not end_dt:
        _append_log("VALIDATION_ERROR", "end cannot be parsed", end=end)
        return _err("VALIDATION_ERROR", "end cannot be parsed", end=end)
    if end_dt is None:
        end_dt = _now()

    if end_dt > start_dt + datetime.timedelta(days=365):
        _append_log("VALIDATION_ERROR", "end must be <= start + 365 days", start=_iso(start_dt), end=_iso(end_dt))
        return _err("VALIDATION_ERROR", "end must be <= start + 365 days", start=_iso(start_dt), end=_iso(end_dt))

    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("rows")
    if not isinstance(networks, list):
        networks = []
    pools = _load("pools.json")
    if isinstance(pools, dict) and "rows" in pools:
        pools = pools.get("rows")
    if not isinstance(pools, list):
        pools = []
    md = _load("pool_market_data.json")
    if isinstance(md, dict) and "rows" in md:
        md = md.get("rows")
    if not isinstance(md, list):
        md = []

    net_key = network.strip().lower()

    def _net_match(nr):
        if not isinstance(nr, dict):
            return False
        nid = (nr.get("id") or "").strip().lower()
        name = (nr.get("name") or "").strip().lower()
        return nid == net_key or (name and name == net_key)

    net = next((n for n in networks if _net_match(n)), None)
    if not net:
        _append_log("NOT_FOUND", "Network not found", network=network)
        return _err("NOT_FOUND", "Network not found", network=network)

    pool_norm = _norm(poolAddress)
    if not pool_norm:
        _append_log("VALIDATION_ERROR", "poolAddress is malformed", poolAddress=poolAddress)
        return _err("VALIDATION_ERROR", "poolAddress is malformed", poolAddress=poolAddress)

    pool = None
    for p in pools:
        if not isinstance(p, dict):
            continue
        if (p.get("network_id") or "").strip().lower() != (net.get("id") or "").strip().lower():
            continue
        if _norm(p.get("address_normalized") or p.get("address_raw") or "") == pool_norm:
            pool = p
            break
    if not pool:
        _append_log("NOT_FOUND", "Pool not found", network=network, poolAddress=poolAddress)
        return _err("NOT_FOUND", "Pool not found", network=network, poolAddress=poolAddress)

    pool_id = pool.get("id")
    rows = []
    for r in md:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "ohlcv":
            continue
        if r.get("pool_id") != pool_id:
            continue
        if r.get("interval") != interval:
            continue
        bdt = _parse_any_dt(r.get("bucket_start_at"))
        if not bdt:
            continue
        if bdt < start_dt or bdt > end_dt:
            continue
        rows.append((bdt, r))

    rows.sort(key=lambda x: x[0])  # ascending
    rows = rows[:limit]
    out = []
    for bdt, r in rows:
        item = {
            "bucket_start_at": r.get("bucket_start_at"),
            "open": r.get("open"),
            "high": r.get("high"),
            "low": r.get("low"),
            "close": r.get("close"),
            "volume": r.get("volume"),
            "status": r.get("status"),
        }
        if inversed:
            def _inv(x):
                try:
                    xv = float(x)
                except Exception:
                    return x
                if xv == 0:
                    return None
                return 1.0 / xv
            item["open"] = _inv(item["open"])
            item["high"] = _inv(item["high"])
            item["low"] = _inv(item["low"])
            item["close"] = _inv(item["close"])
        out.append(item)

    _append_log("OK", None, network_id=net.get("id"), pool_id=pool_id, returned=len(out))
    return {
        "network": {"id": net.get("id"), "name": net.get("name")},
        "pool": {"id": pool_id, "address_normalized": pool.get("address_normalized")},
        "interval": interval,
        "start": _iso(start_dt),
        "end": _iso(end_dt),
        "limit": limit,
        "inversed": inversed,
        "items": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None,
    }

