            return False
        nid = (nr.get("id") or "").strip().lower()
        name = (nr.get("name") or "").strip().lower()
        return nid == net_key or (name and name == net_key)

    net = next((n for n in networks if _net_match(n)), None)
    if not net:
        _append_log("NOT_FOUND", "Network not found", network=network)
        return _err("NOT_FOUND", "Network not found", network=network)

    pool_norm = _norm(poolAddress)
    if not pool_norm:
        _append_log("VALIDATION_ERROR", "poolAddress is malformed", poolAddress=poolAddress)
        return _err("VALIDATION_ERROR", "poolAddress is malformed", poolAddress=poolAddress)

    pool = None
    for p in pools:
        if not isinstance(p, dict):
            continue
        if (p.get("network_id") or "").strip().lower() != (net.get("id") or "").strip().lower():
            continue
        if _norm(p.get("address_normalized") or p.get("address_raw") or "") == pool_norm:
            pool = p
            break
    if not pool:
        _append_log("NOT_FOUND", "Pool not found", network=network, poolAddress=poolAddress)
        return _err("NOT_FOUND", "Pool not found", network=network, poolAddress=poolAddress)

    pool_id = pool.get("id")

    tx_rows = []
    for r in md:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "tx":
            continue
        if r.get("pool_id") != pool_id:
            continue
        tx_at = _dt(r.get("tx_at"))
        if not tx_at:
            continue
        tx_id = r.get("tx_id")
        if not isinstance(tx_id, str) or not tx_id:
            continue
        tx_rows.append((tx_at, tx_id, r))

    # Order: tx_at desc then tx_id desc
    tx_rows.sort(key=lambda x: (x[0], x[1]), reverse=True)

    start_index = 0
    if cursor is not None:
        # cursor must match an existing tx_id for that pool
        cursor = cursor.strip()
        found = None
        for i, (_, tid, _) in enumerate(tx_rows):
            if tid == cursor:
                found = i
                break
        if found is None:
            _append_log("VALIDATION_ERROR", "cursor not found for this pool", cursor=cursor, pool_id=pool_id)
            return _err("VALIDATION_ERROR", "cursor not found for this pool", cursor=cursor, pool_id=pool_id)
        start_index = found + 1
    else:
        start_index = page * limit

    items = []
    for _, _, r in tx_rows[start_index : start_index + limit]:
        items.append(r)

    has_more = (start_index + limit) < len(tx_rows)
    next_cursor = None
    if has_more and items:
        next_cursor = items[-1].get("tx_id")

    _append_log("OK", None, network_id=net.get("id"), pool_id=pool_id, returned=len(items))
    return {
        "network": {"id": net.get("id"), "name": net.get("name")},
        "pool": {"id": pool_id, "address_normalized": pool.get("address_normalized")},
        "items": items,
        "page": None if cursor is not None else int(page),
        "limit": limit,
        "total": len(tx_rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

