            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_call(endpoint, req, code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": req,
            "status": code,
            "message": message,
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-2000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= 120:
            return False, cnt
        return True, cnt

    ok, cnt = _enforce_rate_limit()
    if not ok:
        _log_call("search", {"query": query}, "RATE_LIMIT", "Too many requests")
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=120, observed=cnt)

    if not isinstance(query, str) or not query.strip():
        _log_call("search", {"query": query}, "VALIDATION_ERROR", "query is required")
        return _err("VALIDATION_ERROR", "query is required")

    q_raw = query.strip()
    q = q_raw.lower()
    q_norm = q
    if q_norm.startswith("0x"):
        q_norm = "0x" + q_norm[2:]
    q_norm = q_norm.strip()

    is_address_like = bool(re.fullmatch(r"0x[a-f0-9]{40}", q_norm)) or (len(q_norm) >= 20 and re.fullmatch(r"[a-z0-9:_\-]{20,}", q_norm))

    networks = _load("networks.json")
    dexes = _load("dexes.json")
    tokens = _load("tokens.json")
    pools = _load("pools.json")

    results = []

    def _add(kind, row, score, extra=None):
        item = {"type": kind, "score": score, "id": row.get("id")}
        if kind == "network":
            item.update({"network_id": row.get("id"), "name": row.get("name")})
        elif kind == "dex":
            item.update({"dex_id": row.get("id"), "network_id": row.get("network_id"), "slug": row.get("slug"), "name": row.get("name")})
        elif kind == "token":
            item.update({"token_id": row.get("id"), "network_id": row.get("network_id"), "address": row.get("address_normalized"), "symbol": row.get("symbol"), "name": row.get("name"), "is_verified": row.get("is_verified")})
        elif kind == "pool":
            item.update({"pool_id": row.get("id"), "network_id": row.get("network_id"), "dex_id": row.get("dex_id"), "address": row.get("address_normalized"), "token0_id": row.get("token0_id"), "token1_id": row.get("token1_id")})
        if extra:
            item.update(extra)
        results.append(item)

    # Exact address matches first (tokens/pools)
    if is_address_like:
        for t in tokens:
            if isinstance(t, dict) and (t.get("address_normalized") or "").lower() == q_norm:
                _add("token", t, 100)
        for p in pools:
            if isinstance(p, dict) and (p.get("address_normalized") or "").lower() == q_norm:
                _add("pool", p, 100)

    def _contains(hay):
        return isinstance(hay, str) and q in hay.lower()

    # Networks
    for n in networks:
        if not isinstance(n, dict):
            continue
        if (n.get("id") or "").lower() == q:
            _add("network", n, 90)
        elif _contains(n.get("id")) or _contains(n.get("name")):
            _add("network", n, 40)

    # DEXes
    for d in dexes:
        if not isinstance(d, dict):
            continue
        if (d.get("slug") or "").lower() == q:
            _add("dex", d, 85)
        elif (d.get("name") or "").lower() == q:
            _add("dex", d, 80)
        elif _contains(d.get("slug")) or _contains(d.get("name")):
            _add("dex", d, 35)

    # Tokens
    for t in tokens:
        if not isinstance(t, dict):
            continue
        if (t.get("address_normalized") or "").lower() == q_norm:
            continue  # already added exact if address-like
        sym = (t.get("symbol") or "")
        nm = (t.get("name") or "")
        if sym and sym.lower() == q:
            _add("token", t, 75)
        elif nm and nm.lower() == q:
            _add("token", t, 70)
        elif _contains(sym) or _contains(nm):
            _add("token", t, 30)

    # Pools by address contains
    for p in pools:
        if not isinstance(p, dict):
            continue
        if (p.get("address_normalized") or "").lower() == q_norm:
            continue
        if _contains(p.get("address_normalized")):
            _add("pool", p, 25)

    # Deduplicate by (type,id) keeping max score
    best = {}
    for r in results:
        k = (r.get("type"), r.get("id"))
        if k not in best or r.get("score", 0) > best[k].get("score", 0):
            best[k] = r
    results = list(best.values())
    results.sort(key=lambda r: (r.get("score", 0), r.get("type", ""), r.get("id", "")), reverse=True)

    resp = {"data": results, "meta": {"query": q_raw, "count": len(results)}}
    _log_call("search", {"query": q_raw}, "OK")
    return resp

def getStats(network=None, dex=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getStats"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    # ---- logs + RL ----
    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs[-5000:]:
        if not isinstance(r, dict):
            continue
        dt = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if dt and dt >= window_start:
            cnt += 1
    if cnt >= 120:
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "dex": dex},
            "status": "RATE_LIMIT",
            "message": "Too many requests",
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save(logs_file, logs)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=120, observed=cnt)

    def _finish(status_code, payload=None, message=None, **extra):
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "request": {"network": network, "dex": dex},
            "status": status_code,
            "message": message,
            "credential_id": None,
            "workspace_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save(logs_file, logs)
        if payload is not None:
            return payload
        return _err(status_code, message or "Request failed", **extra)

    # ---- validate types ----
    if network is not None and (not isinstance(network, str) or not network.strip()):
        return _finish("VALIDATION_ERROR", None, "network must be a non-empty string when provided", network=network)
    if dex is not None and (not isinstance(dex, str) or not dex.strip()):
        return _finish("VALIDATION_ERROR", None, "dex must be a non-empty string when provided", dex=dex)

    networks = _load("networks.json")
    if isinstance(networks, dict) and "rows" in networks:
        networks = networks.get("data") or networks.get("items") or []
    if not isinstance(networks, list):
        networks = []

    dexes = _load("dexes.json")
    if isinstance(dexes, dict) and "rows" in dexes:
        dexes = dexes.get("data") or dexes.get("items") or []
    if not isinstance(dexes, list):
        dexes = []

    tokens = _load("tokens.json")
    if isinstance(tokens, dict) and "rows" in tokens:
        tokens = tokens.get("data") or tokens.get("items") or []
    if not isinstance(tokens, list):
        tokens = []

    pools = _load("pools.json")
    if isinstance(pools, dict) and "rows" in pools:
        pools = pools.get("data") or pools.get("items") or []
    if not isinstance(pools, list):
        pools = []

    # ---- resolve optional scope ----
    net_row = None
    if network is not None:
        needle = network.strip().lower()
        for n in networks:
            if not isinstance(n, dict):
                continue
            nid = (n.get("id") or "").strip()
            nm = (n.get("name") or "").strip()
            if nid.lower() == needle or (nid.lower().startswith("dxn_") and nid.lower()[4:] == needle) or (nm and nm.lower() == needle):
                net_row = n
                break
        if net_row is None:
            return _finish("NOT_FOUND", None, "Network not found", network=network)

    dex_row = None
    if dex is not None:
        dneedle = dex.strip().lower()
        # if network provided, must be consistent
        for d in dexes:
            if not isinstance(d, dict):
                continue
            if (d.get("id") or "").strip().lower() == dneedle or (d.get("slug") or "").strip().lower() == dneedle:
                if net_row is not None and d.get("network_id") != net_row.get("id"):
                    continue
                dex_row = d
                break
        if dex_row is None:
            return _finish("NOT_FOUND", None, "DEX not found", dex=dex, network=network)

    # ---- filter entities by scope and by active-ish statuses ----
    def _net_ok(n):
        # ignore deprecated
        return isinstance(n, dict) and n.get("status") in (None, "active", "maintenance")

    def _dex_ok(d):
        return isinstance(d, dict) and d.get("status") == "active"

    def _token_ok(t):
        return isinstance(t, dict) and t.get("status") in (None, "active", "flagged")

    def _pool_ok(p):
        return isinstance(p, dict) and p.get("status") in (None, "active", "stale")

    net_id = net_row.get("id") if net_row else None
    dex_id = dex_row.get("id") if dex_row else None

    nets_f = [n for n in networks if _net_ok(n)]
    if net_id is not None:
        nets_f = [n for n in nets_f if n.get("id") == net_id]

    dexes_f = [d for d in dexes if _dex_ok(d)]
    if net_id is not None:
        dexes_f = [d for d in dexes_f if d.get("network_id") == net_id]
    if dex_id is not None:
        dexes_f = [d for d in dexes_f if d.get("id") == dex_id]

    tokens_f = [t for t in tokens if _token_ok(t)]
    if net_id is not None:
        tokens_f = [t for t in tokens_f if t.get("network_id") == net_id]

    pools_f = [p for p in pools if _pool_ok(p)]
    if net_id is not None:
        pools_f = [p for p in pools_f if p.get("network_id") == net_id]
    if dex_id is not None:
        pools_f = [p for p in pools_f if p.get("dex_id") == dex_id]

    # sums only for active pools (rule)
    volume_sum = 0.0
    tx_sum = 0.0
    for p in pools_f:
        if p.get("status") != "active":
            continue
        v = p.get("volume_usd_24h")
        t = p.get("transactions_24h")
        try:
            if v is not None:
                volume_sum += float(v)
        except Exception:
            pass
        try:
            if t is not None:
                tx_sum += float(t)
        except Exception:
            pass

    payload = {
        "scope": {
            "network": {"id": net_row.get("id"), "name": net_row.get("name")} if net_row else None,
            "dex": {"id": dex_row.get("id"), "slug": dex_row.get("slug"), "name": dex_row.get("name")} if dex_row else None,
        },
        "counts": {
            "networks": len(nets_f),
            "dexes": len(dexes_f),
            "tokens": len(tokens_f),
            "pools": len(pools_f),
        },
        "sums": {
            "active_pools_volume_usd_24h": volume_sum,
            "active_pools_transactions_24h": tx_sum,
        },
        "computed_at": _iso(_now()),
    }
    return _finish("OK", payload)

