def getMe(apiKey=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0225000" if __import__("os").path.isdir("./environment_mix/0225000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getMe"
    logs_file = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.isoformat() + "Z"

    def _parse_dt_log(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _append_log(status, message=None, credential_id=None, **extra):
        logs = _load(logs_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "request": {"apiKey": "***" if apiKey else None},
                "status": status,
                "message": message,
                "credential_id": credential_id,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(_now()),
                **extra,
            }
        )
        _save(logs_file, logs)

    # Rate limit: global 60s window
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    observed = 0
    for r in logs[-5000:]:
        if isinstance(r, dict):
            dt = _parse_dt_log(r.get("created_at") or r.get("timestamp"))
            if dt and dt >= window_start:
                observed += 1
    limit_rl = 120
    if observed >= limit_rl:
        _append_log("RATE_LIMIT", "Too many requests", window_seconds=60, limit=limit_rl, observed=observed)
        return _err("RATE_LIMIT", "Too many requests", window_seconds=60, limit=limit_rl, observed=observed)

    # Authenticate: match against client-visible key value OR id.
    # If no apiKey param, resolve any usable active credential context (ambient auth).
    candidate_files = [
        "api_keys.json",
        "credentials.json",
        "keys.json",
        "auth.json",
        "users.json",
        "accounts.json",
    ]

    def _as_rows(obj):
        if isinstance(obj, dict) and "rows" in obj and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    all_rows = []
    source_file = None
    for fn in candidate_files:
        path = os.path.join(_DB, fn)
        if not os.path.exists(path):
            continue
        data = _load(fn)
        rows = _as_rows(data)
        if rows:
            all_rows = rows
            source_file = fn
            break

    def _is_active(row):
        if not isinstance(row, dict):
            return False
        # accept various conventions
        if row.get("active") is False:
            return False
        st = row.get("status")
        if isinstance(st, str) and st.lower() in ("disabled", "revoked", "inactive", "deleted", "blocked"):
            return False
        return True

    def _match_key(row, key):
        if not isinstance(row, dict):
            return False
        if row.get("id") == key:
            return True
        # common visible fields
        for k in ("apiKey", "api_key", "key", "value", "token", "secret", "client_key"):
            v = row.get(k)
            if isinstance(v, str) and v == key:
                return True
        return False

    credential = None
    if apiKey is not None:
        if not isinstance(apiKey, str) or not apiKey.strip():
            _append_log("VALIDATION_ERROR", "apiKey must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "apiKey must be a non-empty string when provided")
        key = apiKey.strip()
        for row in all_rows:
            if _is_active(row) and _match_key(row, key):
                credential = row
                break
        if credential is None:
            _append_log("UNAUTHORIZED", "Invalid API key")
            return _err("UNAUTHORIZED", "Invalid API key")
    else:
        # Ambient: choose any active credential-like row if available; otherwise allow anonymous-ish identity.
        for row in all_rows:
            if _is_active(row):
                credential = row
                break

    # Produce identity/scopes/quota best-effort from available row fields.
    scopes = []
    if isinstance(credential, dict):
        sc = credential.get("scopes") or credential.get("scope")
        if isinstance(sc, list):
            scopes = [str(x) for x in sc if isinstance(x, (str, int, float))]
        elif isinstance(sc, str):
            scopes = [s for s in (x.strip() for x in sc.replace(",", " ").split()) if s]

    # Simple consumption snapshot based on logs (keyed by credential id if we have one)
    cred_id = credential.get("id") if isinstance(credential, dict) else None
    last_minute = 0
    last_day = 0
    day_start = now - datetime.timedelta(days=1)
    for r in logs[-20000:]:
        if not isinstance(r, dict):
            continue
        if cred_id is not None and r.get("credential_id") not in (None, cred_id):
            continue
        dt = _parse_dt_log(r.get("created_at") or r.get("timestamp"))
        if not dt:
            continue
        if dt >= window_start:
            last_minute += 1
        if dt >= day_start:
            last_day += 1

    resp = {
        "credential": credential,
        "scopes": scopes,
        "rate_limit": {
            "window_seconds": 60,
            "limit": limit_rl,
            "observed": observed,
            "observed_for_credential_last_minute": last_minute,
        },
        "usage": {
            "requests_last_24h": last_day,
        },
        "source": source_file,
    }

    _append_log("OK", None, credential_id=cred_id)
    return resp
